    'จบด่านมีโอกาสได้รับไอเทมบัฟ (ยาเพิ่มทอง/HP/ดาเมจ) — โอกาสสูงขึ้นตามดาวที่ได้',
    'เลือกบัฟ 1 ชิ้นก่อนเข้าด่าน บัฟจะถูกใช้อัตโนมัติตอนเริ่มด่านและหมดไป 1 ชิ้น',
