    'เปิด Workshop เพื่อซื้ออัพเกรดถาวร 3 อย่าง: ทองเริ่มต้น +100, HP ปราสาท +5, Awaken ราคาลด 50',
    'ทองถาวรแสดงที่ topbar หน้าเมนูหลัก — แตะเพื่อเปิด Workshop ได้เลย',
