    'เส้นทางเดินของศัตรูมีลูกศรเรืองแสงไหลเป็นจังหวะ มองเห็นทิศทางง่ายขึ้น',
    'เพิ่มเมนู ⚙ ตั้งค่า รวมปุ่มความเร็วเกม / เปิด-ปิดเสียง / ระดับเสียง / Auto Wave ไว้ที่เดียว'
