    'แถบเตือนสภาพอากาศและไอคอนสภาพอากาศมีแสงเรืองตามธีมสีของอันตราย',
    'ป๊อปอัพป้อมปราการมีแสงเรืองเขียวรอบกรอบ ปุ่มอัพเกรด/ขายมีแสงตอน hover',
