    'การ์ดมอนสเตอร์/หอคอยใน Codex มี hover ยกตัว+เรืองแสง และการ์ดที่เลือกอยู่เรืองแสงเขียว',
    'รายการ Ranking มี hover ยกตัวเล็กน้อย, อันดับ 1-3 (เหรียญทอง/เงิน/ทองแดง) เรืองแสงตามสี, แถวของตัวเองเรืองแสงทอง',
