    'หลอดเลือด (HP bar) มีแสงเรืองตามสี',
    'แผงเลือกหอคอย (tower panel) มีเงาเรืองเขียวด้านบน, ปุ่มหอคอยที่เลือกอยู่เรืองแสงเด่นขึ้น และมี hover ยกตัวเล็กน้อย',
